package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PeriodRepository extends JpaRepository<Period, Long> {

    /** The sheet's periods, by from-date. */
    List<Period> findBySheetIdOrderByFromDateAscIdAsc(String sheetId);

    Optional<Period> findByIdAndSheetId(Long id, String sheetId);

    /** Whether a date falls in one of the sheet's closed periods. */
    default boolean isClosedOn(String sheetId, LocalDate date) {
        return date != null && findBySheetIdOrderByFromDateAscIdAsc(sheetId).stream()
                .anyMatch(p -> p.isClosed() && p.contains(date));
    }

    /** Whether a date falls in one of the sheet's soft-closed periods. */
    default boolean isSoftClosedOn(String sheetId, LocalDate date) {
        return date != null && findBySheetIdOrderByFromDateAscIdAsc(sheetId).stream()
                .anyMatch(p -> p.isSoftClosed() && p.contains(date));
    }
}
package net.officefloor.hq.app.period;

import java.time.YearMonth;
import net.officefloor.hq.app.sheet.Sheet;

/** The period generator for other features (not a step): adds a period per calendar month exactly as it does. */
public final class MonthlyPeriods {

    private MonthlyPeriods() {
    }

    /** Adds a period per calendar month from the first month to the last, as the period generator does. */
    public static GeneratedPeriods generate(Sheet sheet, YearMonth firstMonth, YearMonth lastMonth, PeriodRepository repository) {
        return GeneratePeriods.months(sheet, firstMonth, lastMonth, repository);
    }
}
-- Each person's opening balance for a period, added to their carried figure for it (pasted openings add up).
CREATE TABLE period_person_opening (
    period_id BIGINT NOT NULL REFERENCES period (id),
    person_id BIGINT NOT NULL,
    opening DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- Every state a sheet's claim, person, dated grade, period, patron, watch, role, delegation and statement has been
-- saved in, with the sheet's today when it was saved, in the order saved: the last one saved while the sheet's today
-- was on or before a date gives the thing as it stood at the end of that date (an as-of view). A null state: it was
-- deleted then. A thing with no state recorded was saved before this was kept, and stands as it is as of any date.
CREATE TABLE entity_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    kind VARCHAR(40) NOT NULL,
    entity_id BIGINT NOT NULL,
    made_on DATE NOT NULL,
    state CLOB
);
CREATE INDEX entity_history_sheet ON entity_history (sheet_id, kind, id);
